function quoteInfo(){const project=state.project||{};const q=state.quote||{};const defaultNo='QT-'+String(project.id||'').replace(/^PF-20(\d{6})-/,'$1-').replace(/^PF-/,'');return{number:q.number??defaultNo,date:q.date??new Date().toLocaleDateString('th-TH',{day:'2-digit',month:'2-digit',year:'numeric'}),contactName:q.contactName??'',customerTax:q.customerTax??'',customerEmail:q.customerEmail??'',salePhone:q.salePhone??'',saleEmail:q.saleEmail??'',customerName:q.customerName??project.name??'',customerAddress:q.customerAddress??project.location??'',discount:n(q.discount||0),remarks:q.remarks??''}}
function quoteFinancials(){const t=totals(),q=quoteInfo();const discount=Math.min(Math.max(0,q.discount),t.subtotal);const net=t.subtotal-discount;const vat=Math.round(net*7)/100;const grand=+(net+vat).toFixed(2);return {...t,discount,net,vat,grand,deposit:+(grand*.60).toFixed(2),balance:+(grand-+(grand*.60).toFixed(2)).toFixed(2)}}
function bahtText(value){
 const digits=['ศูนย์','หนึ่ง','สอง','สาม','สี่','ห้า','หก','เจ็ด','แปด','เก้า'];
 function group(num){if(num===0)return '';let out='';const str=String(num);for(let i=0;i<str.length;i++){const d=Number(str[i]),p=str.length-i-1;if(!d)continue;if(p===1){out+=d===1?'สิบ':d===2?'ยี่สิบ':digits[d]+'สิบ';}else if(p===0){out+=d===1&&num>1?'เอ็ด':digits[d];}else out+=digits[d]+['','','ร้อย','พัน','หมื่น','แสน'][p];}return out;}
 function read(num){if(num===0)return 'ศูนย์';if(num>=1000000)return read(Math.floor(num/1000000))+'ล้าน'+(num%1000000?group(num%1000000):'');return group(num);}
 const cents=Math.round(Math.max(0,Number(value)||0)*100),baht=Math.floor(cents/100),sat=cents%100;
 return read(baht)+'บาท'+(sat?read(sat)+'สตางค์':'ถ้วน');
}
function quoteField(label,key,value,type='text',attr=''){return `<div class="field"><label>${label}</label><input data-quote-field="${key}" type="${type}" ${type==='number'?'min="0" step="0.01"':''} value="${esc(value)}" ${attr}></div>`}
